{
  "lines": [
    {
      "id": "reflection.weeks",
      "tiers": [
        {
          "id": "reflection.weeks:t1",
          "title": "Погода по ощущениям",
          "phrase": "Отметки ощущений есть в 4 разных неделях — ты знакомишься со своей внутренней погодой. Без гадания на гантелях.",
          "imagePrompt": "A small frog weather keeper in oversized rain boots stands on a low stool, holding a tray of four tiny clouds with different expressions. One cloud drizzles into the tray while the frog leans closer to greet it.",
          "fishMarkup": "[warm]Отметки ощущений есть в 4 разных неделях — ты знакомишься со своей внутренней погодой. Без гадания на гантелях.",
          "audioText": "Отметки ощущений есть в 4 разных неделях — ты знакомишься со своей внутренней погодой. Без гадания на гантелях."
        },
        {
          "id": "reflection.weeks:t2",
          "title": "Архив облачных дел",
          "phrase": "Отметки ощущений охватили 12 разных недель — ты собираешь историю внутренней погоды. Тучам и солнцу нашлось место в одной сводке.",
          "imagePrompt": "A small frog weather keeper in oversized rain boots tends a stepped shelf of open cloud cubbies. Puffy clouds, a sleepy sun and a busy raincloud occupy separate nooks; the frog carefully slides a tray beneath the dripping visitor.",
          "fishMarkup": "[confident]Отметки ощущений охватили <emphasis>12 разных недель</emphasis> — ты собираешь историю внутренней погоды. [playful]Тучам и солнцу нашлось место в одной сводке.",
          "audioText": "Отметки ощущений охватили 12 разных недель — ты собираешь историю внутренней погоды. Тучам и солнцу нашлось место в одной сводке."
        },
        {
          "id": "reflection.weeks:t3",
          "title": "Туча со своим зонтом",
          "phrase": "У тебя отметки ощущений за 26 разных недель — ты ведёшь целую летопись внутренней погоды. Даже грозовая туча пришла с зонтиком.",
          "imagePrompt": "A small frog weather keeper in oversized rain boots welcomes an enormous thundercloud at a tiny reception desk. The cloud squeezes onto a visitor stool beneath its own absurdly small umbrella, while smaller clouds peek around it.",
          "fishMarkup": "[triumphant]У тебя отметки ощущений за <emphasis>26 разных недель</emphasis> — ты ведёшь целую летопись внутренней погоды. [playful]Даже грозовая туча <slow>пришла с зонтиком.</slow>",
          "audioText": "У тебя отметки ощущений за 26 разных недель — ты ведёшь целую летопись внутренней погоды. Даже грозовая туча пришла с зонтиком."
        }
      ]
    },
    {
      "id": "reflection.note",
      "tiers": [
        {
          "id": "reflection.note:t1",
          "title": "Первое слово за тобой",
          "phrase": "Есть первый день с твоей собственной заметкой к тренировке — ты даёшь слово не только железу.",
          "imagePrompt": "A stubby pencil reporter in oversized sneakers holds a tiny microphone beside a gym bench. A single open notebook serves as a lectern, its pages blank; one dumbbell rests opposite like an exceptionally quiet interview guest.",
          "fishMarkup": "[warm]Есть первый день с твоей собственной заметкой к тренировке — ты даёшь слово <soft>не только железу.</soft>",
          "audioText": "Есть первый день с твоей собственной заметкой к тренировке — ты даёшь слово не только железу."
        },
        {
          "id": "reflection.note:t2",
          "title": "Репортаж между гантелями",
          "phrase": "Собственные заметки к тренировкам есть уже за 5 разных дней. Ты пишешь свою историю, пока гантели старательно хранят молчание.",
          "imagePrompt": "A stubby pencil reporter in oversized sneakers builds a compact interview desk from stacked blank notebooks. Leaning across the top, it offers a microphone to two dumbbells, both sitting stubbornly motionless on a gym bench.",
          "fishMarkup": "[confident]Собственные заметки к тренировкам есть уже за <emphasis>5 разных дней.</emphasis> [playful]Ты пишешь свою историю, пока гантели старательно хранят молчание.",
          "audioText": "Собственные заметки к тренировкам есть уже за 5 разных дней. Ты пишешь свою историю, пока гантели старательно хранят молчание."
        },
        {
          "id": "reflection.note:t3",
          "title": "Железо требует слова",
          "phrase": "Собственные заметки к тренировкам есть уже за 15 разных дней — ты ведёшь настоящую хронику. Гантели требуют право на ответ.",
          "imagePrompt": "A stubby pencil reporter in oversized sneakers hosts a press conference behind a giant unfurled blank notebook. Dumbbells crowd the gym bench, leaning eagerly toward its tiny microphone; a long barbell tries to squeeze into the front row.",
          "fishMarkup": "[triumphant]Собственные заметки к тренировкам есть уже за <emphasis>15 разных дней</emphasis> — ты ведёшь настоящую хронику. [playful]Гантели требуют <slow>право на ответ.</slow>",
          "audioText": "Собственные заметки к тренировкам есть уже за 15 разных дней — ты ведёшь настоящую хронику. Гантели требуют право на ответ."
        }
      ]
    }
  ]
}
